-- RecodeX schema.
-- Mirrors src/types.ts. Column names are snake_case; the mapping lives in src/lib/supabase/mapping.ts.
--
-- Design notes
--  * Ids are generated by the app and are only unique per user ("p-101", "pt-two-pointers"), so every
--    primary key is (user_id, id).
--  * There are no foreign keys between app tables. The client writes rows optimistically through a
--    queue, one request per row or chunk, in no guaranteed order (a revision can arrive before its
--    problem during a CSV import). Integrity is kept by the store, as it was before Supabase.
--  * synced_at is set by the server on every insert/update and a delete leaves a row in `deletions`,
--    so a device can fetch only what changed since its last sync.
--  * Every table has row-level security: a user can only see and change their own rows.

-- ---------------------------------------------------------------------------------------------
-- Tables

create table public.user_meta (
  user_id        uuid primary key default auth.uid() references auth.users on delete cascade,
  settings       jsonb not null default '{}'::jsonb,
  next_num       integer not null default 101,
  imported_at    timestamptz,
  schema_version integer not null default 1,
  synced_at      timestamptz not null default now()
);

create table public.patterns (
  user_id      uuid not null default auth.uid() references auth.users on delete cascade,
  id           text not null,
  name         text not null,
  sort_order   double precision not null default 0,
  sub_patterns text[] not null default '{}',
  learning     text not null default 'active' check (learning in ('active', 'yet_to_learn', 'learning', 'completed')),
  description  text not null default '',
  created_at   timestamptz not null default now(),
  synced_at    timestamptz not null default now(),
  primary key (user_id, id)
);

create table public.problems (
  user_id           uuid not null default auth.uid() references auth.users on delete cascade,
  id                text not null,
  num               integer not null,
  name              text not null,
  pattern_id        text not null,
  sub_pattern       text not null default '',
  difficulty        text not null default 'Medium' check (difficulty in ('Easy', 'Medium', 'Hard')),
  url               text not null default '',
  priority          text not null default 'Medium' check (priority in ('High', 'Medium', 'Low')),
  track             text not null default 'active' check (track in ('active', 'backlog')),
  last_rating       text check (last_rating in ('green', 'yellow', 'red')),
  last_revised      date,
  next_review       date,
  phase             text not null default 'Reconstruction' check (phase in ('Reconstruction', 'Recall/Repair', 'Quick Recall')),
  phase_manual      boolean not null default false,
  consecutive_green integer not null default 0,
  revision_count    integer not null default 0,
  weakness          text not null default '',
  notes             text not null default '',
  learned_at        date,
  imported_name     text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  synced_at         timestamptz not null default now(),
  primary key (user_id, id)
);

create table public.revisions (
  user_id     uuid not null default auth.uid() references auth.users on delete cascade,
  id          text not null,
  problem_id  text not null,
  revised_on  date not null,
  revised_at  timestamptz not null,
  rating      text not null check (rating in ('green', 'yellow', 'red')),
  phase       text not null check (phase in ('Reconstruction', 'Recall/Repair', 'Quick Recall')),
  time_min    double precision,
  independent boolean,
  mistake     text not null default '',
  notes       text not null default '',
  session_id  text,
  source      text not null check (source in ('import', 'quick', 'today', 'session')),
  next_review date not null,
  prev_state  jsonb,                 -- problem snapshot before this revision (undo of the latest one)
  synced_at   timestamptz not null default now(),
  primary key (user_id, id)
);

create table public.practice_sessions (
  user_id     uuid not null default auth.uid() references auth.users on delete cascade,
  id          text not null,
  kind        text not null,
  title       text not null,
  config      jsonb,
  problem_ids text[] not null default '{}',
  results     jsonb not null default '[]'::jsonb,   -- SessionResult[], kept inside the session as in the app
  position    integer not null default 0,
  started_at  timestamptz not null default now(),
  ended_at    timestamptz,
  status      text not null default 'in_progress' check (status in ('in_progress', 'completed', 'abandoned')),
  elapsed_sec integer not null default 0,
  synced_at   timestamptz not null default now(),
  primary key (user_id, id)
);

-- One row per deleted record, so other devices learn about deletions during an incremental sync.
create table public.deletions (
  user_id    uuid not null references auth.users on delete cascade,
  tbl        text not null,
  id         text not null,
  deleted_at timestamptz not null default now(),
  primary key (user_id, tbl, id)
);

-- ---------------------------------------------------------------------------------------------
-- Indexes

create index problems_sync on public.problems (user_id, synced_at);
create index problems_due on public.problems (user_id, next_review) where track = 'active';
create index problems_pattern on public.problems (user_id, pattern_id);
create index patterns_sync on public.patterns (user_id, synced_at);
create index revisions_sync on public.revisions (user_id, synced_at);
create index revisions_problem on public.revisions (user_id, problem_id, revised_at);
create index revisions_day on public.revisions (user_id, revised_on);
create index sessions_sync on public.practice_sessions (user_id, synced_at);
create index deletions_sync on public.deletions (user_id, deleted_at);

-- ---------------------------------------------------------------------------------------------
-- Sync bookkeeping

create or replace function public.touch_synced_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.synced_at := now();
  return new;
end;
$$;

-- On delete: remember the id. On insert: forget an older deletion of the same id (a restore re-creates rows).
create or replace function public.track_deletion()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'DELETE' then
    insert into public.deletions (user_id, tbl, id, deleted_at)
    values (old.user_id, tg_table_name, old.id, now())
    on conflict (user_id, tbl, id) do update set deleted_at = excluded.deleted_at;
    return old;
  else
    delete from public.deletions d where d.user_id = new.user_id and d.tbl = tg_table_name and d.id = new.id;
    return new;
  end if;
end;
$$;

revoke all on function public.track_deletion() from public, anon, authenticated;
revoke all on function public.touch_synced_at() from public, anon, authenticated;

create trigger user_meta_touch before insert or update on public.user_meta for each row execute function public.touch_synced_at();

create trigger patterns_touch before insert or update on public.patterns for each row execute function public.touch_synced_at();
create trigger problems_touch before insert or update on public.problems for each row execute function public.touch_synced_at();
create trigger revisions_touch before insert or update on public.revisions for each row execute function public.touch_synced_at();
create trigger sessions_touch before insert or update on public.practice_sessions for each row execute function public.touch_synced_at();

create trigger patterns_deleted after insert or delete on public.patterns for each row execute function public.track_deletion();
create trigger problems_deleted after insert or delete on public.problems for each row execute function public.track_deletion();
create trigger revisions_deleted after insert or delete on public.revisions for each row execute function public.track_deletion();
create trigger sessions_deleted after insert or delete on public.practice_sessions for each row execute function public.track_deletion();

-- ---------------------------------------------------------------------------------------------
-- Row-level security: each signed-in user sees and changes only their own rows.

alter table public.user_meta enable row level security;
alter table public.patterns enable row level security;
alter table public.problems enable row level security;
alter table public.revisions enable row level security;
alter table public.practice_sessions enable row level security;
alter table public.deletions enable row level security;

do $$
declare t text;
begin
  foreach t in array array['user_meta', 'patterns', 'problems', 'revisions', 'practice_sessions'] loop
    execute format('create policy "own rows: select" on public.%I for select to authenticated using ((select auth.uid()) = user_id)', t);
    execute format('create policy "own rows: insert" on public.%I for insert to authenticated with check ((select auth.uid()) = user_id)', t);
    execute format('create policy "own rows: update" on public.%I for update to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id)', t);
    execute format('create policy "own rows: delete" on public.%I for delete to authenticated using ((select auth.uid()) = user_id)', t);
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);
  end loop;
end;
$$;

-- deletions is written only by the trigger; users can read their own entries.
create policy "own rows: select" on public.deletions for select to authenticated using ((select auth.uid()) = user_id);
grant select on public.deletions to authenticated;
